 const selectedOnly=true;
 const r={checkpoint:150,diagnosticCheckpoint:161,variant:new URL(location.href).searchParams.has('reference-only')?'native-reference-only':'native-reference-and-natural-end-master',samples:[],startedAt:new Date().toISOString(),scope:'Actual MP3/real cached SCNet/grid/Sync/Q/Loop-off, ordinary non-loop reverse, forward return, source-start end and Stop; raw and keylock-key3. Physically muted internal PCM. Exact Serato composition/pitch/quality/native/hardware/full parity unverified.',criteria:{minimumRMS:1e-5,maximumStoppedPeak:1e-7,sourceClockErrorSeconds:.01,rawComparisonWindow:[.3,1.3],maximumRawRelativeRMS:1e-4},stages:[],progress:[],errors:[]};let observer,original,track;
